using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using Microsoft.Win32;
namespace StudyDesk {
 public partial class Desktop {
  StackPanel signinTasks,signinCoursePanel;CheckBox autoNormalSignin;readonly Dictionary<string,CheckBox> signinCourseChecks=new Dictionary<string,CheckBox>();bool signinLoading,signinPolicyLoaded;ComboBox signinLocations;TextBox locationName,locationLat,locationLon,locationAddress;LocationMap signinMap;List<Dictionary<string,object>> storedLocations=new List<Dictionary<string,object>>();
  void BuildSignin(){signinPolicyLoaded=false;signinCourseChecks.Clear();var policy=Column();policy.Children.Add(Text("普通签到",20,"#293B58"));policy.Children.Add(Text("仅处理已添加且勾选课程中的普通签到；位置、拍照、手势和签到码不会作为普通签到自动提交。",13,"#78869B"));autoNormalSignin=new CheckBox{Content="开启自动普通签到（每30秒检查所选课程）",Margin=new Thickness(0,10,0,12)};policy.Children.Add(autoNormalSignin);signinCoursePanel=Column();policy.Children.Add(signinCoursePanel);var row=new WrapPanel();row.Children.Add(Button("保存自动签到设置",async()=>await SaveSigninPolicy(),false));row.Children.Add(Button("刷新签到列表",async()=>await LoadSignin(),true));policy.Children.Add(row);content.Children.Add(Card(policy));
   content.Children.Add(Text("签到活动",20,"#293B58"));signinTasks=Column();content.Children.Add(signinTasks);var positions=Column();positions.Children.Add(Text("位置签到 · 常用位置",20,"#293B58"));positions.Children.Add(Text("学习通位置签到要求手机App。这里负责选点与位置管理，准备位置不会提交签到，也不修改Windows系统定位。坐标统一为WGS84；百度、高德坐标请先核对坐标系。",13,"#78869B"));signinLocations=new ComboBox{DisplayMemberPath="Title",Margin=new Thickness(0,6,0,12),MinHeight=36};signinLocations.SelectionChanged+=(s,e)=>SelectStoredLocation();positions.Children.Add(signinLocations);signinMap=new LocationMap();signinMap.Selected=(lat,lon)=>{locationLat.Text=lat.ToString("F7",CultureInfo.InvariantCulture);locationLon.Text=lon.ToString("F7",CultureInfo.InvariantCulture);};positions.Children.Add(signinMap);
   locationName=new TextBox();locationLat=new TextBox();locationLon=new TextBox();locationAddress=new TextBox();positions.Children.Add(Text("位置名称",12,"#78869B"));positions.Children.Add(locationName);var fields=new Grid{Margin=new Thickness(0,9,0,9)};fields.ColumnDefinitions.Add(new ColumnDefinition());fields.ColumnDefinitions.Add(new ColumnDefinition());var latBox=Column();latBox.Margin=new Thickness(0,0,10,0);latBox.Children.Add(Text("纬度 Latitude（-90 至 90）",12,"#78869B"));latBox.Children.Add(locationLat);fields.Children.Add(latBox);var lonBox=Column();lonBox.Children.Add(Text("经度 Longitude（-180 至 180）",12,"#78869B"));lonBox.Children.Add(locationLon);Grid.SetColumn(lonBox,1);fields.Children.Add(lonBox);positions.Children.Add(fields);positions.Children.Add(Text("地址 / 备注",12,"#78869B"));positions.Children.Add(locationAddress);var actions=new WrapPanel();actions.Children.Add(Button("定位到输入坐标",()=>CenterInputLocation(),true));actions.Children.Add(Button("保存常用位置",async()=>await SaveLocation(),false));actions.Children.Add(Button("复制纬度",()=>CopyCoordinate(true),true));actions.Children.Add(Button("复制经度",()=>CopyCoordinate(false),true));actions.Children.Add(Button("删除所选位置",async()=>await DeleteLocation(),true));actions.Children.Add(Button("导入 GPX",async()=>await ImportLocations(),true));actions.Children.Add(Button("导出 GPX",async()=>await ExportLocations(),true));actions.Children.Add(Button("GoGoGo 手机端说明",()=>Open("https://github.com/ZCShou/GoGoGo#readme"),true));positions.Children.Add(actions);var positionToggle=new Expander{Header=Text("地图选点与常用位置（展开）",18,"#293B58"),Content=positions,IsExpanded=false};content.Children.Insert(1,Card(positionToggle));if(ready){var unused=LoadSignin();var unusedLocations=LoadLocations();}}
  class SavedLocationItem{public string Title{get;set;}public Dictionary<string,object> Value{get;set;}}
  async Task LoadSignin(){if(!ready||page!="signin"||signinLoading||signinTasks==null)return;signinLoading=true;int version=scopeVersion;try{var r=await client.RequestAsync("/local/signin/list",null,lifetime.Token);if(page!="signin"||version!=scopeVersion||platform!="chaoxing")return;var data=Data.Map(r,"data");if(!signinPolicyLoaded){var settings=Data.Map(data,"settings");autoNormalSignin.IsChecked=Data.Flag(settings,"autoNormal");var chosen=new HashSet<string>();object raw;if(settings!=null&&settings.TryGetValue("courseKeys",out raw)&&raw is System.Collections.IEnumerable)foreach(object id in (System.Collections.IEnumerable)raw)chosen.Add(Convert.ToString(id));signinCoursePanel.Children.Clear();foreach(var c in Data.Rows(data,"courses")){string id=Data.Text(c,"id");var check=new CheckBox{Content=Data.Text(c,"title"),IsChecked=chosen.Contains(id),Margin=new Thickness(0,0,0,7)};signinCourseChecks[id]=check;signinCoursePanel.Children.Add(check);}signinPolicyLoaded=true;}signinTasks.Children.Clear();int count=0;foreach(var item in Data.Rows(data,"items").OrderByDescending(v=>Data.Flag(v,"ongoing"))){count++;signinTasks.Children.Add(SigninCard(item));}if(count==0)signinTasks.Children.Add(Card(Text("当前已添加课程没有返回签到活动。",15,"#78869B")));Message(Data.Text(data,"message"));}catch(Exception e){Message(Friendly(e));}finally{signinLoading=false;}}
  UIElement SigninCard(Dictionary<string,object> item){var p=Column();string kind=Data.Text(item,"kind"),id=Data.Text(item,"id");var record=Data.Map(item,"record");string state=Data.Text(record,"state");string label=state=="completed"?"已签到":state=="verification"?"等待安全验证":state=="signing"?"签到中":state=="queued"?"排队中":state=="stopped"?"已停止":state=="uncertain"?"待核对":!Data.Flag(item,"ongoing")?"已结束":kind=="location"?"需手机App":Data.Text(item,"platformStatus");p.Children.Add(Text(Data.Text(item,"title")+" · "+label,18,"#293B58"));p.Children.Add(Text(Data.Text(item,"course")+" · "+(kind=="normal"?"普通签到":kind=="location"?"位置签到":"其他签到方式"),13,"#78869B"));p.Children.Add(Text(record==null?Data.Text(item,"detail"):Data.Text(record,"message"),13,"#78869B"));var controls=new WrapPanel();if(kind=="normal"&&Data.Flag(item,"ongoing")&&record==null)controls.Children.Add(Button("普通签到",async()=>await SigninAction(id,"start"),false));if(kind=="location"&&Data.Flag(item,"ongoing"))controls.Children.Add(Button("准备手机位置签到",()=>PreparePhoneLocation(Data.Text(item,"title")),true));if(record!=null)controls.Children.Add(Button("核对平台状态",async()=>await SigninAction(id,"recheck"),true));if(new[]{"queued","signing","verification"}.Contains(state))controls.Children.Add(Button("停止等待",async()=>await SigninAction(id,"stop"),true));p.Children.Add(controls);return Card(p);}
  async Task SaveSigninPolicy(){if(actionBusy)return;actionBusy=true;try{var keys=signinCourseChecks.Where(p=>p.Value.IsChecked==true).Select(p=>p.Key).ToArray();var response=await Write("/local/signin/settings",new Dictionary<string,object>{{"autoNormal",autoNormalSignin.IsChecked==true},{"courseKeys",keys}});Message(Data.Text(response,"msg"));}catch(Exception e){Message(Friendly(e));}finally{actionBusy=false;}}
  async Task SigninAction(string id,string action){if(actionBusy)return;if(action=="start"&&!Confirm("向平台提交这一次普通签到？遇到安全验证时需要在平台窗口完成。"))return;actionBusy=true;try{var body=new Dictionary<string,object>{{"id",id}};if(action=="start")body["confirmed"]=true;var r=await Write("/local/signin/"+action,body);await LoadSignin();Message(Data.Text(r,"msg"));}catch(Exception e){Message(Friendly(e));}finally{actionBusy=false;}}
  async Task LoadLocations(){try{var r=await client.RequestAsync("/local/signin/locations",null,lifetime.Token);if(page!="signin")return;storedLocations=Data.Rows(r,"data").ToList();signinLocations.Items.Clear();foreach(var loc in storedLocations)signinLocations.Items.Add(new SavedLocationItem{Title=Data.Text(loc,"name"),Value=loc});}catch(Exception e){Message(Friendly(e));}}
  void SelectStoredLocation(){var selected=signinLocations.SelectedItem as SavedLocationItem;if(selected==null)return;var p=selected.Value;locationName.Text=Data.Text(p,"name");locationLat.Text=Data.Text(p,"latitude");locationLon.Text=Data.Text(p,"longitude");locationAddress.Text=Data.Text(p,"address");CenterInputLocation();}
  bool InputCoordinates(out double lat,out double lon){bool ok=double.TryParse(locationLat.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out lat)&double.TryParse(locationLon.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out lon);if(!ok||double.IsNaN(lat)||double.IsNaN(lon)||double.IsInfinity(lat)||double.IsInfinity(lon)||lat < -90||lat > 90||lon < -180||lon > 180){Message("请输入有效WGS84坐标：纬度-90至90，经度-180至180。");return false;}return true;}
  void CenterInputLocation(){double lat,lon;if(InputCoordinates(out lat,out lon))signinMap.Center(lat,lon);}
  void CopyCoordinate(bool latitude){double lat,lon;if(!InputCoordinates(out lat,out lon))return;Clipboard.SetText((latitude?lat:lon).ToString("F7",CultureInfo.InvariantCulture));Message("已复制"+(latitude?"纬度":"经度")+"（WGS84），请粘贴到手机端对应字段。");}
  async Task SaveLocation(){double lat,lon;if(!InputCoordinates(out lat,out lon))return;try{await Write("/local/signin/locations/add",new Dictionary<string,object>{{"name",locationName.Text.Trim()},{"latitude",lat},{"longitude",lon},{"address",locationAddress.Text.Trim()}});await LoadLocations();Message("常用位置已保存，尚未提交任何位置签到。");}catch(Exception e){Message(Friendly(e));}}
  async Task DeleteLocation(){var selected=signinLocations.SelectedItem as SavedLocationItem;if(selected==null)return;try{await Write("/local/signin/locations/delete",new Dictionary<string,object>{{"id",Data.Text(selected.Value,"id")}});await LoadLocations();}catch(Exception e){Message(Friendly(e));}}
  void PreparePhoneLocation(string title){double lat,lon;if(!InputCoordinates(out lat,out lon))return;MessageBox.Show(window,title+"\n\n所选位置（WGS84）：\n纬度 "+lat.ToString("F7",CultureInfo.InvariantCulture)+"\n经度 "+lon.ToString("F7",CultureInfo.InvariantCulture)+"\n\n在安卓手机的GoGoGo中输入对应坐标并启用模拟定位，再在学习通手机App中完成签到。此窗口仅准备位置，不会将准备状态显示为签到成功。","手机位置签到",MessageBoxButton.OK,MessageBoxImage.Information);}
  async Task ExportLocations(){try{var r=await Write("/local/signin/locations/export",new Dictionary<string,object>());var data=Data.Map(r,"data");string folder=Path.Combine(Root,"exports");Directory.CreateDirectory(folder);var dialog=new SaveFileDialog{Title="导出WGS84常用位置",Filter="GPX文件|*.gpx",FileName=Data.Text(data,"filename"),InitialDirectory=folder};if(dialog.ShowDialog(window)==true){File.WriteAllBytes(dialog.FileName,Convert.FromBase64String(Data.Text(data,"contentBase64")));Message("已导出GPX位置文件。");}}catch(Exception e){Message(Friendly(e));}}
  async Task ImportLocations(){var dialog=new OpenFileDialog{Title="导入WGS84位置",Filter="GPX文件|*.gpx"};if(dialog.ShowDialog(window)!=true)return;try{var info=new FileInfo(dialog.FileName);if(info.Length>2*1024*1024){Message("GPX文件不能超过2MB。");return;}var r=await Write("/local/signin/locations/import",new Dictionary<string,object>{{"contentBase64",Convert.ToBase64String(File.ReadAllBytes(dialog.FileName))}});await LoadLocations();Message(Data.Text(r,"msg"));}catch(Exception e){Message(Friendly(e));}}
 }
